import torch
from transformers import AutoModelForCausalLM, DynamicCache
torch.set_num_threads(2)
load = lambda name: AutoModelForCausalLM.from_pretrained(name, dtype=torch.float32).eval()
draft, target = load("HuggingFaceTB/SmolLM2-135M"), load("HuggingFaceTB/SmolLM2-360M")

def probs(logits, T):          # T = 0 means greedy: one-hot on the argmax
    if T == 0:
        return torch.nn.functional.one_hot(logits.argmax(-1), logits.shape[-1]).float()
    return torch.softmax(logits / T, dim=-1)

def sample(p, g):
    return torch.multinomial(p, 1, generator=g).item()

@torch.no_grad()
def feed(model, cache, seq):   # run only the tokens this cache has not seen
    new = torch.tensor([seq[cache.get_seq_length():]])
    return model(input_ids=new, past_key_values=cache, use_cache=True).logits[0]

def rollback(cache, keep):     # keep the first `keep` positions, drop the rest
    extra = cache.get_seq_length() - keep
    if extra > 0:
        cache.crop(-extra)     # transformers 5: crop(-n) removes the last n
